KINDS = {"decision": "A choice the room committed to",
         "action": "Something one named person will do",
         "risk": "A problem or dependency raised",
         "question": "Something still unanswered"}

def on_sentence(sentence, speaker):
    state = "%s said: %s" % (speaker, sentence)
    qs = {"kind": {"type": "choice", "criteria": KINDS,
          "instructions": "How should %s's sentence be filed in the minutes?" % speaker},
          "owner": {"type": "noul",
          "instructions": "Does this sentence name the person who will do the work?"}}
    return decide(state, qs)

# units: one per video or document, with a written description and a start time
criteria = {u["id"]: u["topic"] for u in units}
criteria["none"] = "Nothing in this library covers it"

def look_up(question):
    qs = {"unit": {"type": "choice", "criteria": criteria,
          "instructions": "Which lesson covers this question?"},
          "covered": {"type": "noul",
          "instructions": "Does the library actually cover this question?"}}
    ans = decide("Visitor asked: " + question, qs)
    if ans["covered"]["noul"] < 0.6:
        return "No lesson covers this yet."
    u = by_id[ans["unit"]["choice"]]
    return "%s, from %s" % (u["title"], u["start"])

const ICONS = {
  water: 'Glass of water', walk: 'Footsteps', read: 'Open book',
  sleep: 'Crescent moon', meditate: 'Seated figure', gym: 'Dumbbell',
  none: 'Nothing in this set fits'
};

const pickIcon = txt => decide({
  model: 'jev-latest',
  state: txt,
  questions: { icon: { type: 'choice', criteria: ICONS,
    instructions: 'Which icon matches what the user just typed?' } }
}).then(a => a.icon.choice);

field.addEventListener('input', () =>
  renderIcon(await pickIcon(field.value));

const SLOTS = {
  hero:   { trial: 'Start a free trial', demo: 'Book a 20 minute demo',
            docs: 'Read the documentation' },
  proof:  { logos: 'Customer logos', caseStudy: 'One case study',
            quote: 'A single customer quote', none: 'No proof block' },
  cta:    { trial: 'Free trial', demo: 'Book a demo',
            waitlist: 'Join the waitlist' }
};

const state = [
  'Referrer: ' + referrer,
  'Campaign: ' + (utm || 'none'),
  'Company size: ' + (size || 'unknown'),
  'Returning: ' + (isReturning ? 'yes' : 'no')
].join('. ');

const questions = Object.fromEntries(Object.entries(SLOTS).map(
  ([slot, opts]) => [slot, { type: 'choice', criteria: opts,
    instructions: 'Which ' + slot + ' module fits this visitor?' }]));

render(await decide({ model: 'jev-latest', state, questions }));

SHAPES = {"decision": "A closed pick, score or yes and no",
          "writing": "Needs text back, keep the language model",
          "count": "Arithmetic or counting, do it in code",
          "lookup": "Fetching a fact, not judging it"}

def audit(step):
    qs = {"shape": {"type": "choice", "criteria": SHAPES,
          "instructions": "What kind of step is this?"},
          "fits": {"type": "noul",
          "instructions": "Could this step be answered by picking between options you could write down in advance?"}}
    return decide(step, qs)

for step in steps:
    ans = audit(step["text"])
    if ans["shape"]["choice"] == "decision" and ans["fits"]["noul"] > 0.6:
        print(step["id"], step["text"][:70])
